import React, { useState, useRef, useEffect } from 'react'; // ✅ FIXED: Added hooks import
import { ChatPanel } from './ChatPanel';
import { NotesPanel } from './NotesPanel';
import { ParticipantsPanel } from './ParticipantsPanel';
import { WhiteboardPanel } from './WhiteboardPanel';

export const SidePanel = ({ 
  activePanel, 
  setActivePanel, 
  messages, 
  onSendMessage, 
  participants, 
  roomId,
  // ✅ REMOVED: onPlayAudio prop removed completely
  onPlayAnimation 
}) => {
  const [inputText, setInputText] = useState('');
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = (e) => {
    e.preventDefault();
    if (inputText.trim()) {
      onSendMessage(inputText);
      setInputText('');
    }
  };

  return (
    <div className="w-96 bg-slate-900/95 backdrop-blur-lg border-l border-purple-500/20 flex flex-col">
      {/* Tabs */}
      <div className="flex border-b border-purple-500/20">
        <button
          onClick={() => setActivePanel('chat')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'chat'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          💬 Chat
        </button>
        <button
          onClick={() => setActivePanel('participants')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'participants'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          👥 Participants ({participants.length})
        </button>
        <button
          onClick={() => setActivePanel('notes')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'notes'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          📝 Notes
        </button>
        <button
          onClick={() => setActivePanel('whiteboard')}
          className={`flex-1 py-3 font-medium transition-all ${
            activePanel === 'whiteboard'
              ? 'bg-purple-600/20 text-purple-300 border-b-2 border-purple-500'
              : 'text-gray-400 hover:text-purple-300'
          }`}
        >
          🎨 Board
        </button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-hidden">
        {activePanel === 'chat' && (
          <div className="h-full flex flex-col">
            {/* Chat Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
              {messages.length === 0 ? (
                <div className="flex flex-col items-center justify-center h-full text-gray-400">
                  <div className="text-6xl mb-4">💬</div>
                  <p className="text-center">No messages yet.<br/>Start a conversation!</p>
                </div>
              ) : (
                messages.map((msg, idx) => (
                  <div
                    key={idx}
                    className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[80%] px-4 py-3 rounded-2xl shadow-lg ${
                        msg.sender === 'user'
                          ? 'bg-gradient-to-br from-purple-600 to-purple-700 text-white'
                          : 'bg-slate-800 text-gray-100 border border-purple-500/30'
                      }`}
                    >
                      <div className="flex items-start space-x-2">
                        <div className="flex-1">
                          <p className="text-xs text-gray-300 mb-1">
                            {msg.sender === 'user' ? 'You' : companion?.name || 'AI'}
                          </p>
                          <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                        </div>
                      </div>
                      {/* ✅ REMOVED: No play button, no replay - messages are one-time only */}
                      <p className="text-xs text-gray-400 mt-2 text-right">
                        {new Date(msg.timestamp).toLocaleTimeString('en-US', {
                          hour: '2-digit',
                          minute: '2-digit'
                        })}
                      </p>
                    </div>
                  </div>
                ))
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input Form */}
            <form onSubmit={handleSend} className="p-4 border-t border-purple-500/20 bg-slate-900/50">
              <div className="flex space-x-2">
                <input
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  placeholder="Type your message..."
                  className="flex-1 px-4 py-3 bg-slate-800 border border-purple-500/30 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-purple-500 transition-all"
                />
                <button
                  type="submit"
                  disabled={!inputText.trim()}
                  className="px-6 py-3 bg-gradient-to-r from-purple-600 to-purple-700 hover:from-purple-700 hover:to-purple-800 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg font-medium transition-all shadow-lg hover:shadow-purple-500/50"
                >
                  Send
                </button>
              </div>
            </form>
          </div>
        )}

        {activePanel === 'participants' && (
          <div className="h-full overflow-y-auto p-4 space-y-2">
            {participants.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-400">
                <div className="text-6xl mb-4">👥</div>
                <p className="text-center">No participants yet</p>
              </div>
            ) : (
              participants.map((participant, idx) => (
                <div
                  key={idx}
                  className="flex items-center space-x-3 px-4 py-3 bg-slate-800/50 rounded-lg border border-purple-500/20 hover:border-purple-500/40 transition-all"
                >
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center font-bold text-sm">
                    {participant.userId.substring(0, 2).toUpperCase()}
                  </div>
                  <div className="flex-1">
                    <p className="font-medium text-gray-100 text-sm">
                      {participant.userId.substring(0, 20)}...
                    </p>
                    <p className="text-xs text-green-400 flex items-center space-x-1">
                      <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                      <span>Active</span>
                    </p>
                  </div>
                </div>
              ))
            )}
          </div>
        )}

        {activePanel === 'notes' && (
          <NotesPanel roomId={roomId} />
        )}

        {activePanel === 'whiteboard' && (
          <WhiteboardPanel roomId={roomId} />
        )}
      </div>
    </div>
  );
};

export default SidePanel;
